import{_ as a,o as e,c as s,ai as i}from"./chunks/framework.BBSijY9B.js";const g=JSON.parse('{"title":"yt-dlp：视频、音频、字幕一行命令存到本地","description":"支持上千个网站；抽音频、拿字幕交给 AI 做摘要，长视频不用从头看到尾。","frontmatter":{"title":"yt-dlp：视频、音频、字幕一行命令存到本地","description":"支持上千个网站；抽音频、拿字幕交给 AI 做摘要，长视频不用从头看到尾。","tags":["GitHub 高星项目","效率","视频","实测"],"sources":["https://github.com/yt-dlp/yt-dlp","https://github.com/yt-dlp/yt-dlp/wiki/Installation","https://github.com/yt-dlp/yt-dlp/wiki/EJS"],"related":["/cases/markitdown","/cases/ollama","/cases/n8n"],"wordCount":918,"readingTime":3,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"yt-dlp：视频、音频、字幕一行命令存到本地 | WANGXXXL"}],["meta",{"property":"og:description","content":"支持上千个网站；抽音频、拿字幕交给 AI 做摘要，长视频不用从头看到尾。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/cases/yt-dlp"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/cases-yt-dlp-c2a5f34c37.png"}],["meta",{"property":"og:image:alt","content":"yt-dlp：视频、音频、字幕一行命令存到本地 · WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"yt-dlp：视频、音频、字幕一行命令存到本地 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"支持上千个网站；抽音频、拿字幕交给 AI 做摘要，长视频不用从头看到尾。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/cases-yt-dlp-c2a5f34c37.png"}],["meta",{"name":"twitter:image:alt","content":"yt-dlp：视频、音频、字幕一行命令存到本地 · WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/cases/yt-dlp"}]]},"headers":[],"relativePath":"cases/yt-dlp.md","filePath":"cases/yt-dlp.md","lastUpdated":1792571830000}'),o={name:"cases/yt-dlp.md"};function l(n,t,r,d,p,h){return e(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="yt-dlp-视频、音频、字幕一行命令存到本地" tabindex="-1">yt-dlp：视频、音频、字幕一行命令存到本地 <a class="header-anchor" href="#yt-dlp-视频、音频、字幕一行命令存到本地" aria-label="Permalink to &quot;yt-dlp：视频、音频、字幕一行命令存到本地&quot;">​</a></h1><p><strong>你能得到什么</strong>：一条命令把公开视频存成 MP4、抽成 MP3，或者只拿字幕。字幕交给 AI 做摘要，一小时的讲座几分钟就能看完重点；课程和讲座存在本地，通勤路上离线听。<strong>适合</strong>：常看长视频学习、做内容素材整理的人。<strong>不适合</strong>：想下载会员专享或受版权保护内容再传播的人，请只保存你有权保存的内容，并遵守网站条款。</p><h2 id="项目速览" tabindex="-1">项目速览 <a class="header-anchor" href="#项目速览" aria-label="Permalink to &quot;项目速览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>仓库</td><td><a href="https://github.com/yt-dlp/yt-dlp" target="_blank" rel="noopener noreferrer">yt-dlp/yt-dlp</a></td></tr><tr><td>Star</td><td>199,825（截至 2026-10-21）</td></tr><tr><td>许可证</td><td>Unlicense（PyInstaller 打包的可执行文件含 GPLv3+ 代码，整体按 GPLv3+）</td></tr><tr><td>最新版本</td><td>2026.08.19</td></tr><tr><td>它做什么</td><td>命令行音视频下载器，支持上千个网站，能选画质、抽音频、下字幕、批量处理播放列表</td></tr></tbody></table><h2 id="安装指南" tabindex="-1">安装指南 <a class="header-anchor" href="#安装指南" aria-label="Permalink to &quot;安装指南&quot;">​</a></h2><p>合并音视频、转 MP3 都要用到 <strong>FFmpeg</strong>，建议一起装上。</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-O7Ars" id="tab-QyP8Ilh" checked><label data-title="macOS" for="tab-QyP8Ilh">macOS</label><input type="radio" name="group-O7Ars" id="tab-Fm6qgdF"><label data-title="Linux" for="tab-Fm6qgdF">Linux</label><input type="radio" name="group-O7Ars" id="tab-2gMpW_w"><label data-title="Windows" for="tab-2gMpW_w">Windows</label></div><div class="blocks"><div class="language-sh vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yt-dlp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ffmpeg</span></span></code></pre></div><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># pip 方式，[default] 会带上推荐的可选依赖</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -U</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;yt-dlp[default]&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ffmpeg</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 或用发行版自己的包管理器</span></span></code></pre></div><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">winget install </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">source winget </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">id yt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dlp.yt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dlp</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">winget install </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">source winget </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">id Gyan.FFmpeg</span></span></code></pre></div></div></div><p>装完先看版本：<code>yt-dlp --version</code>。用官方独立可执行文件安装的，以后用 <code>yt-dlp -U</code> 升级；用 pip、brew、winget 装的，用对应的包管理器升级。</p><h2 id="使用教程-长视频变成可检索的字幕和音频" tabindex="-1">使用教程：长视频变成可检索的字幕和音频 <a class="header-anchor" href="#使用教程-长视频变成可检索的字幕和音频" aria-label="Permalink to &quot;使用教程：长视频变成可检索的字幕和音频&quot;">​</a></h2><div class="steps"><ol><li><strong>看有哪些清晰度</strong>：<code>yt-dlp -F &quot;视频链接&quot;</code> 列出所有格式。</li><li><strong>存成 MP4</strong>：<code>yt-dlp -f &quot;bv*+ba/b&quot; --merge-output-format mp4 -o &quot;%(title)s.%(ext)s&quot; &quot;视频链接&quot;</code>，最好的画质和音轨合成一个 MP4。</li><li><strong>只要音频</strong>：<code>yt-dlp -x --audio-format mp3 &quot;视频链接&quot;</code>，适合播客、讲座。</li><li><strong>只要字幕</strong>：<code>yt-dlp --write-subs --write-auto-subs --sub-langs &quot;zh-Hans,en&quot; --skip-download &quot;视频链接&quot;</code>，拿到 <code>.vtt</code> 字幕文件。</li><li><strong>交给 AI</strong>：把字幕文件内容贴给 AI，让它按时间线列要点；配合本地的 <a href="/cases/ollama">Ollama</a>，整个过程不用把内容发到外部服务。</li></ol></div><h2 id="避坑与解决方案" tabindex="-1">避坑与解决方案 <a class="header-anchor" href="#避坑与解决方案" aria-label="Permalink to &quot;避坑与解决方案&quot;">​</a></h2><h3 id="提示-no-supported-javascript-runtime-could-be-found" tabindex="-1">提示 No supported JavaScript runtime could be found <a class="header-anchor" href="#提示-no-supported-javascript-runtime-could-be-found" aria-label="Permalink to &quot;提示 No supported JavaScript runtime could be found&quot;">​</a></h3><p>新版 yt-dlp 处理 YouTube 时需要一个 JavaScript 运行时，没有的话会给出这条警告，部分格式可能拿不到。我们这次实测就出现了这条警告，好在测试视频的格式仍然完整。<strong>解决</strong>：装 <a href="https://deno.land" target="_blank" rel="noopener noreferrer">deno</a>（官方默认启用、推荐）；已经装了 Node.js 的，可以加 <code>--js-runtimes node</code>。详见官方 <a href="https://github.com/yt-dlp/yt-dlp/wiki/EJS" target="_blank" rel="noopener noreferrer">EJS 说明</a>。</p><h3 id="下字幕报-http-error-429-too-many-requests" tabindex="-1">下字幕报 HTTP Error 429: Too Many Requests <a class="header-anchor" href="#下字幕报-http-error-429-too-many-requests" aria-label="Permalink to &quot;下字幕报 HTTP Error 429: Too Many Requests&quot;">​</a></h3><p>我们用 <code>--sub-langs &quot;en.*&quot;</code> 下自动字幕时，通配符匹配到了一堆「英语翻译成其他语言」的自动字幕，连续请求后被限流，报 429。<strong>解决</strong>：语言写精确，比如 <code>--sub-langs en</code> 或 <code>zh-Hans,en</code>；先用 <code>--list-subs</code> 看有哪些字幕再挑。</p><h3 id="提示没有可用的-impersonate-target" tabindex="-1">提示没有可用的 impersonate target <a class="header-anchor" href="#提示没有可用的-impersonate-target" aria-label="Permalink to &quot;提示没有可用的 impersonate target&quot;">​</a></h3><p>有些网站需要模拟浏览器请求，没装相关依赖时会提示这条警告。<strong>解决</strong>：用 pip 安装时带上 <code>curl-cffi</code> 这个可选依赖：<code>pip install &quot;yt-dlp[default,curl-cffi]&quot;</code>。</p><h3 id="合并或转-mp3-失败" tabindex="-1">合并或转 MP3 失败 <a class="header-anchor" href="#合并或转-mp3-失败" aria-label="Permalink to &quot;合并或转 MP3 失败&quot;">​</a></h3><p>没装 FFmpeg 时，分开下载的视频和音频无法合并，<code>-x</code> 抽音频也会失败。装好 FFmpeg 并确保它在 <code>PATH</code> 里。</p><h3 id="突然大面积失效" tabindex="-1">突然大面积失效 <a class="header-anchor" href="#突然大面积失效" aria-label="Permalink to &quot;突然大面积失效&quot;">​</a></h3><p>视频网站经常改版，旧版本 yt-dlp 失效很常见。遇到「昨天还能用、今天不行」，先升级到最新版再说。</p><h2 id="wangxxxl-实测于-2026-10-21" tabindex="-1">WANGXXXL 实测于 2026-10-21 <a class="header-anchor" href="#wangxxxl-实测于-2026-10-21" aria-label="Permalink to &quot;WANGXXXL 实测于 2026-10-21&quot;">​</a></h2><ul><li><strong>环境</strong>：Linux 云电脑，Python 3.12 虚拟环境，<code>uv pip install &quot;yt-dlp[default]&quot;</code> 装到 2026.08.19 版，系统已有 FFmpeg。</li><li><strong>测试视频</strong>：YouTube 上第一支视频「Me at the zoo」（19 秒）。</li><li><strong>结果</strong>：<code>-F</code> 正常列出格式（同时出现上面说的 JavaScript 运行时警告）；最佳画质加音轨合并成 MP4 约 1.6 秒，文件 476 KB；<code>-x --audio-format mp3</code> 约 1.7 秒得到 121 KB 的 MP3；<code>--sub-langs &quot;en.*&quot;</code> 拿到了英文字幕，但请求翻译字幕时报 429。</li></ul>`,23)])])}const u=a(o,[["render",l]]);export{g as __pageData,u as default};
